# PointChess 2-Billion Position Modern HalfKAv2 NNUE Trainer on Kaggle 2x Tesla T4 GPUs
import os, sys, base64, subprocess, torch

print("=" * 65)
print(" PointChess 2-Billion Position NNUE Trainer (11.5M Params | 2x T4 DDP)")
print("=" * 65)

num_gpus = torch.cuda.device_count()
print(f"PyTorch: {torch.__version__} | CUDA: {torch.cuda.is_available()} | GPUs: {num_gpus}")
for i in range(num_gpus):
    print(f"  GPU {i}: {torch.cuda.get_device_name(i)}")

print("\n[Step 1/5] Unpacking PointChess source code...")
os.chdir("/kaggle/working")
b64_payload = ""
with open("/tmp/pointchess_src.tar.gz", "wb") as out:
    out.write(base64.b64decode(b64_payload))
subprocess.run(["tar", "-xzf", "/tmp/pointchess_src.tar.gz", "-C", "/kaggle/working"], check=True)

print("\n[Step 2/5] Compiling PointChess C++ engine with Release optimizations...")
os.makedirs("/kaggle/working/build", exist_ok=True)
subprocess.run("cd /kaggle/working/build && cmake -DCMAKE_BUILD_TYPE=Release /kaggle/working && make -j$(nproc)", shell=True, check=True)
subprocess.run("/kaggle/working/build/pointchess bench 64 1 8", shell=True, check=True)

# Check for uploaded Kaggle Dataset
input_dataset = "/kaggle/input/pointchess-200k-dataset/pointchess_200k_tactical.txt"
if os.path.exists(input_dataset):
    data_file = input_dataset
    print(f"\n[Step 3/5] Using uploaded Kaggle Dataset: {data_file} ({os.path.getsize(data_file)/1024/1024:.2f} MB)")
else:
    print("\n[Step 3/5] Mining tactical weaknesses with 200,000 self-play games...")
    data_file = "/kaggle/working/selfplay_200k.txt"
    subprocess.run(f"/kaggle/working/build/pointchess genselfplay 200000 $(nproc) 2 {data_file}", shell=True, check=True)

print("\n[Step 4/5] Training 2-Billion Positions on Kaggle 2x T4 GPUs (DDP + SCReL + AMP fp16)...")
ckpt_dir = "/kaggle/working/checkpoints_2b"
os.makedirs(ckpt_dir, exist_ok=True)
if num_gpus >= 2:
    train_cmd = f"cd /kaggle/working/training && torchrun --nproc_per_node=2 train_4b.py --data_file {data_file} --max_positions 2000000000 --batch_size 4096 --lr 2e-3 --output_dir {ckpt_dir}"
else:
    train_cmd = f"cd /kaggle/working/training && python3 train_4b.py --data_file {data_file} --max_positions 2000000000 --batch_size 4096 --lr 2e-3 --output_dir {ckpt_dir}"
subprocess.run(train_cmd, shell=True, check=True)

print("\n[Step 5/5] Exporting custom .pchess and .pnet network files...")
out_pchess = "/kaggle/working/pointchess.pchess"
out_pnet = "/kaggle/working/nnue.pnet"
export_cmd = f"cd /kaggle/working/training && python3 export.py --checkpoint {ckpt_dir}/best_model.pt --output_pchess {out_pchess} --output_pnet {out_pnet}"
subprocess.run(export_cmd, shell=True, check=True)

print("\n" + "=" * 65)
print(" 2-Billion Training complete! pointchess.pchess saved to /kaggle/working/pointchess.pchess")
print("=" * 65)
